// v28.xx (cw-guncraft), HIS ORDER (2026-10-15): "guns more expensive to craft". Every gun recipe below costs exactly twice what it did
// (SMG was comp4 cell3 board2 servo1, Carbine comp4 servo2 board2, Rifle comp5 servo2 board3 optic1, Scattergun comp5 cell4 board2 servo2).
// The other recipes above are untouched.
{name:'Compact SMG',out:{gun_smg:1},need:{comp:8,cell:6,board:4,servo:2}},
{name:'Burst Carbine',out:{gun_carbine:1},need:{comp:8,servo:4,board:4}},
{name:'Auto Rifle',out:{gun_rifle:1},need:{comp:10,servo:4,board:6,optic:2}},
{name:'Riot Scattergun',out:{gun_shotgun:1},need:{comp:10,cell:8,board:4,servo:4}}

check:
{v:'VER',what:'every gun recipe on the bench costs twice its old amount and a non-gun recipe is unchanged (his order: guns more expensive to craft)',
 run:function(){
   if(typeof RECIPES==='undefined') return 'SKIP: no recipes in this build';
   var old={gun_smg:{comp:4,cell:3,board:2,servo:1},gun_carbine:{comp:4,servo:2,board:2},gun_rifle:{comp:5,servo:2,board:3,optic:1},gun_shotgun:{comp:5,cell:4,board:2,servo:2}};
   var bad=[], seen=0, i, k, r, out, medOk=false, fragOk=false;
   __runPrep(); __topClear(); __resetCfg(); __pinDefaults(0); __cleanProfile();
   try{
     for(i=0;i<RECIPES.length;i++){
       r=RECIPES[i]; out=null; for(k in r.out){ out=k; break; }
       if(old[out]){
         seen++;
         for(k in old[out]) if(r.need[k]!==old[out][k]*2) bad.push(r.name+' needs '+r.need[k]+' '+k+' and not '+old[out][k]*2);
         for(k in r.need) if(old[out][k]===undefined) bad.push(r.name+' gained '+k);
       }
       if(out==='medkit'&&r.need.bandage===2&&r.need.comp===1) medOk=true;
       if(out==='frag'&&r.need.comp===2&&r.need.cell===2&&r.need.scrap===2) fragOk=true;
     }
     if(seen!==4) bad.push('found '+seen+' gun recipes and not four');
     if(!medOk) bad.push('the Medkit recipe changed');
     if(!fragOk) bad.push('the Frag Charge recipe changed');
     return bad.length?bad.join('; '):null;
   } finally { __topClear(); } }},
